  'math.title': 'Kopfrechnen',
  'math.intro': 'Eine sichere Methode für jede Rechenart — mit Beispielen aus unseren Lektionen und einem Trainer.',
  'math.op.add': 'Addition',
  'math.op.sub': 'Subtraktion',
